/** Width and height in pixels of a saved QR code image; large enough to print. */
private const val SAVED_IMAGE_SIZE = 1024

/**
 * Shows the QR code for a campsite. Scanning it in the app opens the campsite's
 * details screen. Save Image opens Android's save dialog so the owner can choose
 * where to store a PNG of the code; no storage permission is needed.
 *
 * @param campsiteId the campsite's Firestore ID.
 * @param campsiteName shown under the code and used to suggest the file name.
 * @param onDismiss called when the user taps Close or outside the dialog.
 */
@Composable
fun CampsiteQrDialog(
    campsiteId: String,
    campsiteName: String,
    onDismiss: () -> Unit,
) {
    val context = LocalContext.current
    val qrImage = remember(campsiteId) { qrBitmap(campsiteId, size = 512)?.asImageBitmap() }
    var saveMessage by remember { mutableStateOf<String?>(null) }

    val saveLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.CreateDocument("image/png")
    ) { uri ->
        if (uri != null) {
            saveMessage = if (saveQrPng(context, uri, campsiteId)) {
                "QR code saved."
            } else {
                "Couldn't save the QR code. Try another location."
            }
        }
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        modifier = Modifier.testTag("qrCodeDialog"),
        title = { Text("Campsite QR Code") },
        text = {
            Column(
                modifier = Modifier.fillMaxWidth(),
                horizontalAlignment = Alignment.CenterHorizontally,
            ) {
                if (qrImage != null) {
                    Image(
                        bitmap = qrImage,
                        contentDescription = "QR code for $campsiteName",
                        modifier = Modifier.size(240.dp).testTag("qrCodeImage"),
                    )
                } else {
                    Text("Couldn't create a QR code for this campsite.")
                }
                Spacer(modifier = Modifier.height(8.dp))
                Text(campsiteName, textAlign = TextAlign.Center)
                Text(
                    "Scan this code in the app to open this campsite.",
                    textAlign = TextAlign.Center,
                )
                saveMessage?.let {
                    Spacer(modifier = Modifier.height(8.dp))
                    Text(it, textAlign = TextAlign.Center, modifier = Modifier.testTag("qrSaveMessage"))
                }
            }
        },
        confirmButton = {
            TextButton(onClick = onDismiss, modifier = Modifier.testTag("closeQrButton")) { Text("Close") }
        },
        dismissButton = {
            TextButton(
                onClick = {
                    saveMessage = null
                    saveLauncher.launch(CampsiteQrCode.fileNameFor(campsiteName))
                },
                enabled = qrImage != null,
                modifier = Modifier.testTag("saveQrButton"),
            ) { Text("Save Image") }
        },
    )
}

/**
 * Draws [campsiteId]'s QR code as a black-on-white bitmap [size] pixels wide,
 * or returns null if the ID can't be encoded.
 */
private fun qrBitmap(campsiteId: String, size: Int): Bitmap? = runCatching {
    val matrix = CampsiteQrCode.encode(CampsiteQrCode.linkFor(campsiteId), size)
    val pixels = IntArray(matrix.width * matrix.height) { i ->
        if (matrix.get(i % matrix.width, i / matrix.width)) Color.BLACK else Color.WHITE
    }
    Bitmap.createBitmap(pixels, matrix.width, matrix.height, Bitmap.Config.ARGB_8888)
}.getOrNull()

/**
 * Writes a [SAVED_IMAGE_SIZE] PNG of [campsiteId]'s QR code to [uri].
 *
 * @return true if the image was saved.
 */
private fun saveQrPng(context: Context, uri: Uri, campsiteId: String): Boolean = runCatching {
    val bitmap = qrBitmap(campsiteId, SAVED_IMAGE_SIZE) ?: return false
    context.contentResolver.openOutputStream(uri)?.use { out ->
        bitmap.compress(Bitmap.CompressFormat.PNG, 100, out)
    } ?: false
}.getOrDefault(false)
